required = set(T['en'])
for locale, values in T.items():
    missing = required - set(values)
    if missing:
        raise SystemExit(f'{locale}: missing localized keys {sorted(missing)}')

p = Path('lib/localization/app_strings.dart')
s = p.read_text()
old = "  String t(String key) {\n    final localized = _values[languageCode]?[key];\n    return localized ?? _en[key] ?? key;\n  }\n"
new = "  String t(String key) {\n    final extra = _extraValues[languageCode]?[key];\n    if (extra != null) return extra;\n    final localized = _values[languageCode]?[key];\n    return localized ?? _en[key] ?? key;\n  }\n"
if old not in s:
    raise SystemExit('AppStrings t() target not found')
s = s.replace(old, new, 1)
lines = ['\n  static const Map<String, Map<String, String>> _extraValues = {']
for locale, values in T.items():
    lines.append(f"    {json.dumps(locale, ensure_ascii=False)}: {{")
    for k, v in values.items():
        lines.append(f"      {json.dumps(k, ensure_ascii=False)}: {json.dumps(v, ensure_ascii=False)},")
    lines.append('    },')
lines.append('  };\n')
block = '\n'.join(lines)
pos = s.rfind('\n}')
if pos < 0:
    raise SystemExit('AppStrings closing brace not found')
s = s[:pos] + block + s[pos:]
p.write_text(s)
print('Run42 strings applied; locale key parity OK')
